PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?person { dbr:Nedo_Sonetti dbr:Michalis_Boukouvalas }
  OPTIONAL { ?person dbo:birthDate ?dboDate. }
  OPTIONAL { ?person dbp:birthDate ?dbpDate. }
  OPTIONAL { ?person dbp:birth_date ?dbp_date. }
  BIND(COALESCE(?dboDate, ?dbpDate, ?dbp_date) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?personLabel. FILTER(lang(?personLabel) = "en") }
}
ORDER BY ?birthDate

